sys_script_client.script:
function onLoad() {

    var assignGroup = g_form.getValue('assignment_group');
    var assignedTo = g_form.getValue('assigned_to');

    if (assignGroup) {
        var ga = new GlideAjax('MSSTaskizeUtils');
        ga.addParam('sysparm_name', 'getUserAssignmentGroupAccess');
        ga.addParam('sysparm_groupSysId', assignGroup);
        ga.getXMLAnswer(function(response) {
            if (response === 'true') {
                if (!assignedTo && g_form.getValue('state') == 1) {
                    g_form.setValue('assigned_to', g_user.userID);
                    g_form.submit('save_taskize_case');
                    return;
                } else if (assignedTo && assignedTo != g_user.userID && (g_form.getValue('state') == 1 || g_form.getValue('state') == 2)) {
                    var ans = confirm("You are viewing a record which is already assigned to someone else" + ". Do you still want to work on it?");
                    if (!ans) {
                        makeFormReadOnly();
                    } else {
                        g_form.setValue('assigned_to', g_user.userID);
                        g_form.submit('save_taskize_case');
                        return;
                    }

                }

            } else {
                makeFormReadOnly();
            }
        });
    } else {
        //makeFormReadOnly();
    }

}

function makeFormReadOnly() {
    var fields = g_form.getEditableFields();
    for (var i = 0; i < fields.length; i++) {
        var fieldName = fields[i];
        if (g_form.isMandatory(fieldName)) {
            g_form.setMandatory(fieldName, false); // Make non-mandatory if it is mandatory
        }
        g_form.setReadOnly(fieldName, true); // Set the field to read-only
    }
}
